<script setup lang="ts">
import { reactive, ref } from 'vue'; import { api } from '@/api'; import { categories } from '@/utils/labels'; import { ElMessage } from 'element-plus'; import { useRouter } from 'vue-router'
const router = useRouter(); const loading = ref(false); const form = reactive({ postType: 'LOST', title: '', description: '', category: '', location: '', occurredAt: '', contact: '', imageUrl: '' })
async function submit() { loading.value = true; try { await api.post('/items', form); ElMessage.success('发布成功，请等待管理员审核'); router.push('/center') } finally { loading.value = false } }
</script>
<template><section class="form-page"><div class="page-title"><span class="eyebrow">PUBLISH INFORMATION</span><h1>发布信息</h1><p>详细、真实的信息能显著提高找回效率。</p></div><el-form label-position="top" class="paper-form" @submit.prevent="submit"><el-form-item label="信息类型"><el-radio-group v-model="form.postType" size="large"><el-radio-button value="LOST">我丢失了物品</el-radio-button><el-radio-button value="FOUND">我捡到了物品</el-radio-button></el-radio-group></el-form-item><div class="two-columns"><el-form-item label="物品标题"><el-input v-model="form.title" maxlength="120" show-word-limit placeholder="例如：在图书馆丢失蓝色校园卡"/></el-form-item><el-form-item label="物品分类"><el-select v-model="form.category" placeholder="请选择"><el-option v-for="item in categories" :key="item.value" v-bind="item"/></el-select></el-form-item></div><el-form-item label="详细描述"><el-input v-model="form.description" type="textarea" :rows="5" maxlength="2000" show-word-limit placeholder="请描述颜色、品牌、外观特征等信息，注意隐藏敏感内容"/></el-form-item><div class="two-columns"><el-form-item label="发生地点"><el-input v-model="form.location" placeholder="例如：第一教学楼 302"/></el-form-item><el-form-item label="发生时间"><el-date-picker v-model="form.occurredAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="请选择日期和时间"/></el-form-item></div><div class="two-columns"><el-form-item label="联系方式"><el-input v-model="form.contact" placeholder="手机号、微信或约定联系渠道"/></el-form-item><el-form-item label="图片地址（选填）"><el-input v-model="form.imageUrl" placeholder="请输入公开可访问的图片链接"/></el-form-item></div><div class="form-actions"><el-button size="large" @click="router.back()">取消</el-button><el-button type="primary" size="large" :loading="loading" native-type="submit">提交审核</el-button></div></el-form></section></template>
